async function renewActiveSession(){try{await rotateSession();}catch(error){if(error.status===401){await signOut();return;}sessionTimer=setTimeout(renewActiveSession,retryRefreshMs);}}
async function rotateSession(){const result=await api("/auth/session/rotate",{method:"POST",csrf:true,body:{}});csrfToken=result.csrfToken;scheduleSessionRotation();}
async function api(path,options={}){const body=options.body===undefined?undefined:JSON.stringify(options.body);const perform=async()=>{for(let attempt=0;attempt<2;attempt++){const headers={};if(body!==undefined)headers["content-type"]="application/json";if(options.csrf){if(!csrfToken)throw new Error("Sign in again to continue.");headers["x-openza-csrf"]=csrfToken;}const response=await fetch(path,{method:options.method||"GET",headers,body,credentials:"same-origin",cache:"no-store",signal:options.signal});const result=await response.json().catch(()=>({}));if(response.ok)return result;const error=new Error(result?.error?.message||"Personal Cloud rejected the request.");error.status=response.status;error.code=result?.error?.code;if(options.csrf&&attempt===0&&response.status===403&&result?.error?.code==="csrf_failed"){try{const session=await api("/auth/session");if(typeof session.csrfToken!=="string"||!session.csrfToken)throw new Error("Owner token refresh was not confirmed.");csrfToken=session.csrfToken;}catch(refreshError){error.cause=refreshError;throw error;}continue;}throw error;}};return options.csrf&&navigator.locks?.request?navigator.locks.request("openza-owner-session-write",perform):perform();}
function registrationOptions(value){return{challenge:decode(value.challenge),rp:value.rp,user:{...value.user,id:decode(value.user.id)},pubKeyCredParams:value.pubKeyCredParams,timeout:value.timeout,attestation:value.attestation,authenticatorSelection:value.authenticatorSelection};}
function assertionOptions(value){return{challenge:decode(value.challenge),rpId:value.rpId,allowCredentials:value.allowCredentials.map(item=>({...item,id:decode(item.id)})),userVerification:value.userVerification,timeout:value.timeout};}
function registrationCredential(value){return{id:value.id,clientDataJSON:encode(value.response.clientDataJSON),attestationObject:encode(value.response.attestationObject)};}
function assertionCredential(value){return{id:value.id,clientDataJSON:encode(value.response.clientDataJSON),authenticatorData:encode(value.response.authenticatorData),signature:encode(value.response.signature)};}
function decode(value){const normalized=value.replace(/-/g,"+").replace(/_/g,"/").padEnd(Math.ceil(value.length/4)*4,"=");const binary=atob(normalized);return Uint8Array.from(binary,char=>char.charCodeAt(0));}
function encode(value){const bytes=new Uint8Array(value);let binary="";bytes.forEach(byte=>binary+=String.fromCharCode(byte));return btoa(binary).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");}
function setStatus(state,label){statusPill.className=`status-pill ${state}`;statusLabel.textContent=label;}
function setNotice(title,body){notice.classList.toggle("confirmed",title==="Cloud copy confirmed");notice.replaceChildren();const heading=document.createElement("strong"),detail=document.createElement("span");heading.textContent=title;detail.textContent=body;notice.append(heading,detail);}
function readCache(){try{const cached=JSON.parse(localStorage.getItem(cacheKey));if(cached?.payload?.protocolVersion!==1||cached.payload.product!=="tasks"||!Array.isArray(cached.payload.tasks))return null;return cached;}catch{return null;}}
function formatTime(value){const date=new Date(value);if(Number.isNaN(date.valueOf()))return"Unknown time";return new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(date);}

async function addNamedLabel(){const task=currentPayload.tasks.find(item=>item.id===selectedTaskId),name=$("#details-new-label").value.trim();if(!currentEditable||detailLabelBusy||!task||!name)return;clearDialogError(detailsDialog);if(task.labels.some(item=>item.name.localeCompare(name,undefined,{sensitivity:"accent"})===0)){const status=$("#details-command-status");status.hidden=false;status.textContent="This task already has that label.";return;}if(new TextEncoder().encode(name).length>512){showDialogError(detailsDialog,"Label name is too long. Shorten it and try again.");return;}const label=currentPayload.labels.find(item=>item.name.localeCompare(name,undefined,{sensitivity:"accent"})===0)||{id:`label_${crypto.randomUUID().replaceAll("-","")}`,name};await updateSelectedLabel("task.addLabel",{label},true);}
async function updateSelectedLabel(operation,payload,clearName=false){const task=currentPayload.tasks.find(item=>item.id===selectedTaskId);if(!currentEditable||detailLabelBusy||!task)return;const taskId=task.id,dirty=Object.keys(captureDetailDraft()).length>0,fields=readDetailFields(),baseline=detailTaskBaseline;detailLabelBusy=true;setDialogBusy(detailsDialog,true);try{const receipt=await sendMutation(taskId,task.entityVersion,operation,payload);if(dirty&&baseline?.id===taskId&&baseline.entityVersion===task.entityVersion&&receipt?.entityId===taskId&&receipt.entityVersion===task.entityVersion+1&&detailTaskBaseline===baseline)detailTaskBaseline={...baseline,entityVersion:receipt.entityVersion};await finishMutations();if(detailsDialog.open&&selectedTaskId===taskId){if(clearName)$("#details-new-label").value="";if(dirty){const refreshed=currentPayload.tasks.find(item=>item.id===taskId);if(refreshed)renderDetailLabels(refreshed);restoreDetailDraft(fields);}else openDetails(taskId,{refresh:true});}}catch(error){if(detailsDialog.open&&selectedTaskId===taskId)showDialogError(detailsDialog,error.message);else setNotice("Label change not saved",error.message);}finally{detailLabelBusy=false;setDialogBusy(detailsDialog,false);}}

function readDetailFields(){return Object.fromEntries(["details-title","details-notes","details-space","details-project","details-status","details-priority","details-planned","details-deadline"].map(id=>[id,document.getElementById(id).value]));}
function captureDetailDraft(){return Object.fromEntries(Object.entries(readDetailFields()).filter(([id,value])=>value!==detailBaseline[id]));}
function restoreDetailDraft(draft){if("details-space" in draft)fillProjectSelect($("#details-project"),draft["details-space"],draft["details-project"]||"");for(const [id,value] of Object.entries(draft))document.getElementById(id).value=value;}

function renderGlobalSearch(){const search=$("#global-search-input").value,scope=$("#search-scope").value==="all"?ALL_SPACES:selectedSpaceId,results=searchWorkspace(currentPayload,search,scope,$("#search-completed").checked),host=$("#global-search-results");$("#global-search-status").textContent=search.trim()?`${results.length} results (up to 25).`:"Search titles, notes and source descriptions.";host.replaceChildren();for(const result of results){const button=document.createElement("button");button.type="button";button.className="subtask-link";button.textContent=`${result.kind==="project"?"Project: ":""}${result.kind==="project"?result.item.name:result.item.title} · ${currentPayload.spaces.find(s=>s.id===result.item.spaceId)?.name||"Space"}`;button.addEventListener("click",()=>{$("#global-search-dialog").close();selectedSpaceId=result.item.spaceId;if(result.kind==="project")selectProject(result.item.id);else{selectedProjectId=null;currentView=result.item.completionState==="completed"?"completed":"all";applyContextPreferences();persistWorkspaceState();renderSidebar();renderTaskList();openDetails(result.item.id);}});host.append(button);}}

function contextKey(){return `${selectedSpaceId}|${selectedProjectId?`project:${selectedProjectId}`:`view:${currentView}`}`;}
function applyContextPreferences(){const defaults={"sort-select":"priority","sort-direction":"default","group-select":selectedProjectId||currentView==="all"?"project":["calendar","overdue"].includes(currentView)?"date":currentView==="completed"?"completed":"none"},controls={...defaults,...viewPreferences[contextKey()]};if((currentView==="all"||selectedProjectId)&&sharedGroups[selectedSpaceId])controls["group-select"]=sharedGroups[selectedSpaceId];for(const id of controlIds){const control=document.getElementById(id),value=controls[id]||"";control.value=[...control.options].some(option=>option.value===value)?value:defaults[id]||"";}}

function renderInitialStatus(copy){
  const host=$("#initial-sync-status"),list=$("#initial-sync-devices");
  const previousState=initialUploadState;
  initialUploadState=copy.state??null;
  $("#initial-sync-title").textContent=({unknown:"Upload status unavailable",unavailable:"Upload status unavailable",complete:"Initial upload complete"})[initialUploadState]||copy.title;$("#initial-sync-title").title=copy.title;$("#initial-sync-detail").textContent=copy.detail;
  list.replaceChildren(...copy.devices.map((text,index)=>{const row=document.createElement("li");row.textContent=text;const measure=copy.progress?.[index];if(measure&&(measure.total!==null||measure.uploading)){const progress=document.createElement("progress");progress.setAttribute("aria-label",measure.label);if(measure.total!==null&&measure.value!==null){progress.max=measure.total;progress.value=measure.value;}row.append(document.createElement("br"),progress);}return row;}));
  host.hidden=false;if(previousState!==initialUploadState)host.open=["uploading","blocked","interrupted"].includes(initialUploadState);
  if(currentEditable&&previousState!==initialUploadState)renderTaskList();
}

function renderEmptyTaskList(canAdd){
  const copy=initialEmptyState(initialUploadState,currentPayload.tasks.length>0),empty=document.createElement("div"),heading=document.createElement("h2"),detail=document.createElement("p");
  empty.className="empty-state";heading.textContent=copy.title;detail.textContent=copy.detail;empty.append(heading,detail);
  if(canAdd){const button=document.createElement("button");button.type="button";button.textContent="Add task";button.addEventListener("click",openAddTask);empty.append(button);}taskList.append(empty);
}

function persistProjectPreferences(){try{localStorage.setItem("openza-personal-cloud-project-preferences",JSON.stringify({sort:$("#project-sort").value,direction:$("#project-direction").value,favorites:$("#project-favorites").checked,status:$("#project-status").value}));}catch{}}
function restoreProjectPreferences(){try{const saved=JSON.parse(localStorage.getItem("openza-personal-cloud-project-preferences"));if(["default","name","created","updated","count"].includes(saved?.sort))$("#project-sort").value=saved.sort;if(["default","reverse"].includes(saved?.direction))$("#project-direction").value=saved.direction;if(typeof saved?.favorites==="boolean")$("#project-favorites").checked=saved.favorites;if(["active","completed","archived","all"].includes(saved?.status))$("#project-status").value=saved.status;}catch{}}
